mapper.delete:
delete from STL_SEC_RECON where SEQ_NO  in(
    select SEQ_NO from STL_SEC_RECON_DEAL where TRADE_DATE = STR_TO_DATE(#{execDate},'%Y%m%d')

)

delete from STL_SEC_RECON_DETAIL where SEQ_NO  in(
    select SEQ_NO from STL_SEC_RECON_DEAL where TRADE_DATE = STR_TO_DATE(#{execDate},'%Y%m%d')

)

mapper.sql:
SELECT STR_TO_DATE(T1.JYRQ, '%Y%m%d') TRADE_DATE, T4.CUSTOMER_ID CUSTOMER_ID, CJBH TRADE_ID, WTBH INSTRUCTION_ID, CASE WHEN T1.BZLB in ('RMB', '人民币') THEN 'CNY' WHEN T1.BZLB in ('HKD', '港币') THEN 'HKD' WHEN T1.BZLB in ('USD', '美元') THEN 'USD' END CCY, CASE WHEN JYLB = '1' THEN '03' WHEN JYLB = '上海' THEN '03' WHEN JYLB = '2' THEN '04' WHEN JYLB = '深圳' THEN '04' END TRADE_MARKET , T5.SEC_ACCT_ID SEC_ACCT_ID, XWBH SEAT_NUMBER, '' SETTLEMEN_TYPE, CJSL TRADE_NUM, CASE WHEN T1.GZZLX !=0 THEN CJJG ELSE NULL END PRICE, YJLX UNIT, CASE WHEN T1.GZZLX !=0 THEN null ELSE CJJG END FULL_PRICE, GZZLX INT_AMT, CJJE TRADE_AMT, NULL TOTAL_TEEAMT, NULL HGDQR, NULL HGDQJE, YHS STAMP_FEE, NULL JSF_AMT, GHF GHF_AMT, NULL ZGF_AMT, NULL SETTLE_FEE, NULL TRADE_FEE, NULL OTHER_FEEAMT, YJ COMMISSION_AMT, CASE WHEN CJJE >0 THEN 'T02' ELSE 'T01' END PS, T2.ACCT_NO ACCOUT, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID, FPT.TYPE_8 AS FINPROD_TYPE FROM INTERF_DZD T1 LEFT JOIN STL_SEC_ACCT_INFO T5 ON T5.BOND_ID = T1.ZQZH LEFT JOIN STL_CAPACCT_INFO T2 ON T5.TRD_ACCT_ID = T2.ACCT_NO and T5.TRD_ACCT_CCY = T2.CCY LEFT JOIN MST_SALE_DEPARTMENT msd ON T2.OWN_DEPT = msd.SALE_DEPID and ((T5.TRADE_PLACE = '03' and msd.SH_SEATNO = T1.XWBH) or (T5.TRADE_PLACE = '04' and msd.SZ_SEATNO = T1.XWBH) ) LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = CONCAT(T1.ZQDM,CASE WHEN T5.TRADE_PLACE = '03' THEN '.SH' WHEN T5.TRADE_PLACE = '04' then '.SZ' END) LEFT JOIN FIN_PRODUCT_TYPE FPT ON T3.FINPROD_ID = FPT.FINPROD_ID LEFT JOIN MST_SEAT T4 ON T4.SEAT_ID = T1.XWBH
EXISTS (SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.JYLB = T1.JYLB AND T6.YWBS = T1.YWBS AND ZYBS IS NULL)
and T4.CUSTOMER_ID IN
#{item.customerId}
and T3.FINPROD_ID not in
#{item.finprodId}
and T1.WTBH not in
#{item.entrustTradeId}
and T1.CJBH not in
#{item.entrustTradeId}
UNION ALL SELECT STR_TO_DATE(T1.JYRQ, '%Y%m%d') TRADE_DATE, T4.CUSTOMER_ID CUSTOMER_ID, LSH TRADE_ID, WTBH INSTRUCTION_ID, CASE WHEN T1.BZ in ('0', '人民币') THEN 'CNY' WHEN T1.BZ in ('1', '港币') THEN 'HKD' WHEN T1.BZ in ('2', '美元') THEN 'USD' END CCY, CASE WHEN JYSC = '1' THEN '03' WHEN JYSC = '上海' THEN '03' WHEN JYSC = '0' THEN '04' WHEN JYSC = '深圳' THEN '04' END TRADE_MARKET , T5.SEC_ACCT_ID SEC_ACCT_ID, XWDM SEAT_NUMBER, JSFS SETTLEMEN_TYPE, case when SJSF > 0 then abs(CJSL) * -1 else abs(CJSL) end as TRADE_NUM, CJJJ PRICE, DWYJLX UNIT, CJQJ FULL_PRICE, YJLXZE INT_AMT, case when SJSF > 0 then abs(QJCJJE) else abs(QJCJJE) * -1 end as TRADE_AMT, FYHJ TOTAL_TEEAMT, STR_TO_DATE(HGDQR, '%Y%m%d') HGDQR, HGDQJE HGDQJE, YHS STAMP_FEE, JSF JSF_AMT, GHF GHF_AMT, ZGF ZGF_AMT, QSF SETTLE_FEE, JYGF TRADE_FEE, QTF OTHER_FEEAMT, JYJ COMMISSION_AMT, CASE WHEN QJCJJE >0 THEN 'T02' ELSE 'T01' END PS, T2.ACCT_NO ACCOUT, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID, FPT.TYPE_8 AS FINPROD_TYPE FROM INTERF_ZX_ZJGFLS T1 LEFT JOIN STL_SEC_ACCT_INFO T5 ON T5.BOND_ID = T1.ZQZH LEFT JOIN STL_CAPACCT_INFO T2 ON T5.TRD_ACCT_ID = T2.ACCT_NO and T5.TRD_ACCT_CCY = T2.CCY LEFT JOIN MST_SALE_DEPARTMENT msd ON T2.OWN_DEPT = msd.SALE_DEPID and ((T1.JYSC in ('1', '上海') and msd.SH_SEATNO = T1.XWDM) or (T1.JYSC in ('0', '深圳') and msd.SZ_SEATNO = T1.XWDM) ) LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = CONCAT(T1.ZQDM,CASE WHEN T1.JYSC = '0' THEN '.SZ' WHEN T1.JYSC = '深圳' THEN '.SZ' WHEN T1.JYSC = '1' then '.SH' WHEN T1.JYSC = '上海' then '.SH' END) LEFT JOIN FIN_PRODUCT_TYPE FPT ON T3.FINPROD_ID = FPT.FINPROD_ID LEFT JOIN MST_SEAT T4 ON T4.SEAT_ID = T1.XWDM WHERE T1.JYSC IN ('0', '1', '深圳', '上海') and EXISTS (SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.ZYBS = T1.ZYDM AND ZYBS IS NOT NULL)
AND T4.CUSTOMER_ID IN
#{item.customerId}
and T3.FINPROD_ID not in
#{item.finprodId}
and T1.WTBH not in
#{item.entrustTradeId}
and T1.LSH not in
#{item.entrustTradeId}
